package com.mannvaasam.model; import jakarta.persistence.*; import java.math.*; import java.time.*;
@Entity @Table(name="products",indexes={@Index(name="idx_product_category",columnList="category_id"),@Index(name="idx_product_active",columnList="active")}) public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String name; @Column(length=4000) public String description; @ManyToOne(optional=false) @JoinColumn(name="category_id") public Category category; @ManyToOne(optional=false) public User seller; @Column(nullable=false,precision=12,scale=2) public BigDecimal price; public String unit,imageUrl; public Integer stock; public boolean active=true; public Instant createdAt=Instant.now(); public Instant updatedAt=Instant.now(); }